const ROLE_TO_CONFIG_KEY = {
    admin: "admin",
    collaborator: "collaborator",
    contributor: "contributor",
    billing_manager: "billingManager",
};
export function isGlobalRewardSettings(rewards) {
    if (!rewards || typeof rewards !== "object") {
        return false;
    }
    return "evmNetworkId" in rewards;
}
export function resolveRewardSettingsForRole(rewards, role) {
    if (!rewards) {
        return null;
    }
    if (isGlobalRewardSettings(rewards)) {
        return rewards;
    }
    const key = ROLE_TO_CONFIG_KEY[role];
    const config = rewards[key];
    return config ?? null;
}
export function rewardConfigKey(config) {
    return JSON.stringify([config.evmNetworkId, config.erc20RewardToken, config.evmPrivateEncrypted]);
}
