function getBaseUrl(url) {
    try {
        const urlObject = new URL(url);
        return `${urlObject.protocol}//${urlObject.host}${urlObject.pathname}`;
    }
    catch {
        return url;
    }
}
export function areBaseUrlsEqual(url1, url2) {
    return getBaseUrl(url1) === getBaseUrl(url2);
}
