import { Value } from "@sinclair/typebox/value";
import { decodePermits } from "@ubiquity-os/permit-generation";
import { createHash } from "crypto";
import Decimal from "decimal.js";
import * as fs from "fs";
import { JSDOM } from "jsdom";
import { stringify } from "yaml";
import { CommentAssociation, CommentKind } from "../configuration/comment-types";
import { githubCommentConfigurationType } from "../configuration/github-comment-config";
import { isAdmin, isCollaborative } from "../helpers/checkers";
import { GITHUB_COMMENT_PAYLOAD_LIMIT } from "../helpers/constants";
import { getGithubWorkflowRunUrl } from "../helpers/github";
import { getTaskReward } from "../helpers/label-price-extractor";
import { createStructuredMetadata } from "../helpers/metadata";
import { getUserRewardRole } from "../helpers/permissions";
import { commentTypeReplacer, removeKeyFromObject } from "../helpers/result-replacer";
import { isGlobalRewardSettings, resolveRewardSettingsForRole, rewardConfigKey } from "../helpers/reward-settings";
import { ERC20_ABI, Erc20Wrapper, getContract, PERMIT2_ABI, Permit2Wrapper } from "../helpers/web3";
import { BaseModule } from "../types/module";
import { PERMIT2_ADDRESS } from "../types/permit2";
/**
 * Posts a GitHub comment according to the given results.
 */
export class GithubCommentModule extends BaseModule {
    _configuration = this.context.config.incentives.githubComment;
    _debugFilePath = "./output.html";
    _tokenSymbolCache = new Map();
    _userRewardSettingsCache = new Map();
    /**
     * Ensures that a string containing special characters get HTML encoded.
     */
    _encodeHTML(str) {
        const dom = new JSDOM();
        const div = dom.window.document.createElement("div");
        div.appendChild(dom.window.document.createTextNode(str));
        return div.innerHTML;
    }
    async _getRewardSettingsForUser(username) {
        if (this._userRewardSettingsCache.has(username)) {
            return this._userRewardSettingsCache.get(username) ?? null;
        }
        const rewards = this.context.config.rewards;
        let resolved = null;
        if (rewards) {
            if (isGlobalRewardSettings(rewards)) {
                resolved = rewards;
            }
            else {
                const role = await getUserRewardRole(this.context, username);
                resolved = resolveRewardSettingsForRole(rewards, role);
            }
        }
        this._userRewardSettingsCache.set(username, resolved);
        return resolved;
    }
    async _getTokenSymbolForConfig(config) {
        const key = rewardConfigKey(config);
        const cached = this._tokenSymbolCache.get(key);
        if (cached) {
            return cached;
        }
        const tokenContract = await getContract(config.evmNetworkId, config.erc20RewardToken, ERC20_ABI);
        const symbol = await new Erc20Wrapper(tokenContract).getSymbol();
        this._tokenSymbolCache.set(key, symbol);
        return symbol;
    }
    async _getTokenDisplayForUser(username) {
        const settings = await this._getRewardSettingsForUser(username);
        if (!settings) {
            return { symbol: "XP", hasToken: false };
        }
        const symbol = await this._getTokenSymbolForConfig(settings);
        return { symbol, hasToken: true };
    }
    _getPayoutMode(result) {
        const someReward = Object.values(result)[0];
        return someReward?.payoutMode;
    }
    /**
     * Generates content when it needs to be stripped due to length limits
     */
    async _getStrippedContent(result, taskReward) {
        const bodyArray = [];
        this.context.logger.info("Stripping content due to excessive length.");
        bodyArray.push("> [!NOTE]\n");
        bodyArray.push("> This output has been truncated due to the comment length limit.\n\n");
        for (const [key, value] of Object.entries(result)) {
            // Remove result with 0 total from being displayed
            if (result[key].total <= 0)
                continue;
            result[key].evaluationCommentHtml = await this._generateHtml(key, value, taskReward, true);
            bodyArray.push(result[key].evaluationCommentHtml);
        }
        const metadata = createStructuredMetadata("GithubCommentModule", {
            workflowUrl: this._encodeHTML(getGithubWorkflowRunUrl()),
            payoutMode: this._getPayoutMode(result),
        });
        const body = bodyArray.join("");
        const raw = `${body}${metadata}`;
        return { body, metadata, raw };
    }
    async isRewardClaimed(reward) {
        if (!reward.permitUrl) {
            return false;
        }
        const permitBase64 = new URL(reward.permitUrl).searchParams.get("claim");
        if (!permitBase64) {
            return false;
        }
        const permits = decodePermits(permitBase64);
        if (!permits.length) {
            return false;
        }
        for (const permit of permits) {
            const { owner, nonce, networkId } = permit;
            const permit2Contract = await getContract(networkId, PERMIT2_ADDRESS, PERMIT2_ABI);
            const permit2Wrapper = new Permit2Wrapper(permit2Contract);
            if (!(await permit2Wrapper.isNonceClaimed(owner, nonce))) {
                return false;
            }
        }
        return true;
    }
    async getBodyContent(data, result, stripContent = false) {
        const taskReward = await getTaskReward(this.context, data.self);
        if (stripContent) {
            return this._getStrippedContent(result, taskReward);
        }
        const keysToRemove = [];
        const bodyArray = [];
        for (const [key, value] of Object.entries(result)) {
            // Remove result with 0 total from being displayed
            if (result[key].total <= 0) {
                keysToRemove.push(key);
                continue;
            }
            result[key].evaluationCommentHtml = await this._generateHtml(key, value, taskReward);
            bodyArray.push(result[key].evaluationCommentHtml);
        }
        // Remove evaluationCommentHtml because it is superfluous
        let metadataResult = removeKeyFromObject(result, "evaluationCommentHtml");
        // Remove user with 0 result from metadataResult
        for (const key of keysToRemove) {
            metadataResult = removeKeyFromObject(metadataResult, key);
        }
        // Add the workflow run url and the metadata in the GitHub's comment
        bodyArray.push(createStructuredMetadata("GithubCommentModule", {
            workflowUrl: this._encodeHTML(getGithubWorkflowRunUrl()),
            output: JSON.parse(JSON.stringify(metadataResult, commentTypeReplacer, 2)
                .replace(/</g, "&lt;")
                .replace(/>/g, "&gt;")
                .replace(/--/g, "&#45;&#45;")
                .replace(/`/g, "&#96;")),
        }));
        const body = bodyArray.join("");
        // We check this length because GitHub has a comment length limit
        if (body.length > GITHUB_COMMENT_PAYLOAD_LIMIT) {
            // First, we try to diminish the metadata content to only contain the URL
            bodyArray[bodyArray.length - 1] = `${createStructuredMetadata("GithubCommentModule", {
                workflowUrl: this._encodeHTML(getGithubWorkflowRunUrl()),
                payoutMode: this._getPayoutMode(result),
            })}`;
            const newBody = bodyArray.join("");
            if (newBody.length <= GITHUB_COMMENT_PAYLOAD_LIMIT) {
                const metadata = bodyArray[bodyArray.length - 1];
                const bodyOnly = bodyArray.slice(0, -1).join("");
                return { body: bodyOnly, metadata, raw: newBody };
            }
            else {
                return this.getBodyContent(data, result, true);
            }
        }
        const metadata = bodyArray[bodyArray.length - 1];
        const bodyOnly = bodyArray.slice(0, -1).join("");
        return { body: bodyOnly, metadata, raw: body };
    }
    async _handlePostComment(data, result, content) {
        const isIssueCollaborative = isCollaborative(data);
        const isUserAdmin = data.self?.user ? await isAdmin(data.self.user.login, this.context) : false;
        try {
            if (Object.values(result).some((v) => v.permitUrl ?? v.explorerUrl) || isIssueCollaborative || isUserAdmin) {
                const comment = await this.context.commentHandler.postComment(this.context, this.context.logger.info(!content.body ? `_No user got rewards at this time._` : content.raw), {
                    raw: true,
                    updateComment: true,
                });
                if (comment) {
                    const issue = "issue" in this.context.payload ? this.context.payload.issue : this.context.payload.pull_request;
                    await this.context.adapters.supabase.location.upsert({
                        issue_id: issue.id,
                        node_url: `${issue.html_url}#issuecomment-${comment.id}`,
                        repository_id: this.context.payload.repository.id,
                        comment_id: comment.id,
                        node_type: "Issue",
                    });
                }
            }
            else {
                const errorLog = this.context.logger.warn("Issue is non-collaborative. Skipping permit generation.");
                await this.context.commentHandler.postComment(this.context, errorLog);
            }
        }
        catch (e) {
            this.context.logger.error(`Could not post GitHub comment`, { e });
        }
    }
    async transform(data, result) {
        const content = await this.getBodyContent(data, result);
        if (this._configuration?.debug) {
            fs.writeFileSync(this._debugFilePath, content.raw);
        }
        if (this._configuration?.post) {
            await this._handlePostComment(data, result, content);
        }
        return result;
    }
    get enabled() {
        if (!Value.Check(githubCommentConfigurationType, this._configuration)) {
            this.context.logger.warn("The configuration for the module GithubCommentModule is invalid or missing, disabling.");
            return false;
        }
        return true;
    }
    _createContributionRows(result, sortedTasks) {
        const content = [];
        function buildContributionRow(view, contribution, count, reward) {
            return `
          <tr>
            <td>${view}</td>
            <td>${contribution}</td>
            <td>${count}</td>
            <td>${reward ?? "-"}</td>
          </tr>`;
        }
        if (result.task?.reward) {
            const taskLabel = result.task.category === "stale" ? "Stale task reward" : "Task";
            content.push(buildContributionRow("Issue", taskLabel, result.task.multiplier, result.task.reward));
        }
        if (result.simplificationReward && result.simplificationReward.files.length !== 0) {
            const totalSimplificationReward = result.simplificationReward.files.reduce((sum, { reward }) => sum.add(reward), new Decimal(0));
            content.push(buildContributionRow("Issue", "Task Simplification", 1, totalSimplificationReward));
        }
        if (result.reviewRewards && this.isPullRequest()) {
            const reviewCount = result.reviewRewards.reduce((total, reviewReward) => total + (reviewReward.reviews?.length ?? 0), 0);
            const totalReviewReward = result.reviewRewards.reduce((sum, reviewReward) => sum.add(reviewReward.reviews?.reduce((subSum, review) => subSum.add(review.reward), new Decimal(0)) ??
                new Decimal(0)), new Decimal(0));
            if (reviewCount > 0) {
                content.push(buildContributionRow("Review", "Code Review", reviewCount, totalReviewReward.toNumber()));
            }
        }
        if (!sortedTasks) {
            return content.join("");
        }
        if (sortedTasks.issues.specification) {
            content.push(buildContributionRow("Issue", "Specification", 1, sortedTasks.issues.specification.score?.reward));
        }
        if (sortedTasks.issues.comments.length) {
            content.push(buildContributionRow("Issue", "Comment", sortedTasks.issues.comments.length, sortedTasks.issues.comments.reduce((acc, curr) => acc.add(curr.score?.reward ?? 0), new Decimal(0))));
        }
        if (sortedTasks.reviews.specification) {
            content.push(buildContributionRow("Review", "Specification", 1, sortedTasks.reviews.specification.score?.reward));
        }
        if (sortedTasks.reviews.comments.length && this.isPullRequest()) {
            content.push(buildContributionRow("Review", "Comment", sortedTasks.reviews.comments.length, sortedTasks.reviews.comments.reduce((acc, curr) => acc.add(curr.score?.reward ?? 0), new Decimal(0))));
        }
        return content.join("");
    }
    _createIncentiveRows(sortedTasks) {
        const content = [];
        if (!sortedTasks) {
            return content.join("");
        }
        function buildIncentiveRow(commentScore) {
            // Properly escape carriage returns for HTML rendering
            const formatting = stringify({
                content: commentScore.score?.formatting,
                regex: commentScore.score?.words,
                ...(commentScore.score?.weight !== undefined && { weight: commentScore.score.weight }),
                authorship: commentScore.score?.authorship,
            }).replace(/[\n\r]/g, "&#13;");
            // Makes sure any HTML injected in the templated is not rendered itself
            const sanitizedContent = commentScore.content
                .replaceAll("&", "&amp;")
                .replaceAll("<", "&lt;")
                .replaceAll(">", "&gt;")
                .replaceAll("`", "&#96;")
                .replace(/([\s\S]{64}).[\s\S]+/, "$1&hellip;");
            return `
          <tr>
            <td>
              <h6>
                <a href="${commentScore.url}" target="_blank" rel="noopener">${sanitizedContent}</a>
              </h6>
            </td>
            <td>
            <details>
              <summary>
                ${new Decimal(commentScore.score?.words?.result ?? 0).add(new Decimal(commentScore.score?.formatting?.result ?? 0)).toDecimalPlaces(3)}
              </summary>
              <pre>${formatting}</pre>
             </details>
            </td>
            <td>
              Relevance: ${commentScore.score?.relevance === undefined ? "-" : commentScore.score.relevance}<br/>
              <span title="Flesch-Kincaid readability score. Higher scores indicate easier to read text (0-30: very difficult, 30-50: difficult, 50-60: fairly difficult, 60-70: standard, 70-80: fairly easy, 80-90: easy, 90-100: very easy)" style="cursor: help;">Readability</span>: ${commentScore.score?.readability?.fleschKincaid === undefined ? "-" : commentScore.score.readability.fleschKincaid.toFixed(1)}
            </td>
            <td>${commentScore.score?.priority === undefined ? "-" : commentScore.score.priority}</td>
            <td>${commentScore.score?.reward === undefined ? "-" : commentScore.score.reward}</td>
          </tr>`;
        }
        if (sortedTasks.issues.specification) {
            content.push(buildIncentiveRow(sortedTasks.issues.specification));
        }
        if (sortedTasks.reviews.specification) {
            content.push(buildIncentiveRow(sortedTasks.reviews.specification));
        }
        for (const issueComment of sortedTasks.issues.comments) {
            content.push(buildIncentiveRow(issueComment));
        }
        if (this.isPullRequest()) {
            for (const reviewComment of sortedTasks.reviews.comments) {
                content.push(buildIncentiveRow(reviewComment));
            }
        }
        return content.join("");
    }
    _createSimplificationRows(result) {
        if (!result.simplificationReward || Object.keys(result.simplificationReward.files).length === 0)
            return "";
        const rows = [];
        for (const file of result.simplificationReward.files) {
            rows.push(`
        <tr>
          <td><a href="${result.simplificationReward.url}/files#diff-${createHash("sha256").update(file.fileName).digest("hex")}" target="_blank" rel="noopener">${file.fileName}</a></td>
          <td>${file.reward}</td>
          <td>${file.additions}</td>
          <td>${file.deletions}</td>
        </tr>`);
        }
        return `
    <h6>Simplification Details for&nbsp;<a href="${result.simplificationReward.url}" target="_blank" rel="noopener">#${result.simplificationReward.url.split("/").slice(-1)[0]}</a></h6>
    <table>
      <thead>
        <tr>
          <th>Filename</th>
          <th>Reward</th>
          <th>Additions</th>
          <th>Deletions</th>
        </tr>
      </thead>
      <tbody>
        ${rows.join("")}
      </tbody>
    </table>`;
    }
    _createReviewRows(result) {
        if (result.reviewRewards?.every((reviewReward) => reviewReward.reviews?.length === 0) || !result.reviewRewards) {
            return "";
        }
        function buildReviewRow(review) {
            return `
        <tr>
          <td>+${review.effect.addition} -${review.effect.deletion}</td>
          <td>${review.priority ?? "-"}</td>
          <td>${review.reward}</td>
        </tr>`;
        }
        const reviewTables = result.reviewRewards
            .filter((reviewReward) => reviewReward.reviews && reviewReward.reviews.length > 0)
            .map((reviewReward) => {
            const rows = reviewReward.reviews?.map(buildReviewRow).join("") ?? "";
            return `
          <h6>Review Details for&nbsp;<a href="${reviewReward.url}" target="_blank" rel="noopener">#${reviewReward.url.split("/").slice(-1)[0]}</a></h6>
          <table>
            <thead>
              <tr>
                <th>Changes</th>
                <th>Priority</th>
                <th>Reward</th>
              </tr>
            </thead>
            <tbody>
              ${rows}
            </tbody>
          </table>`;
        })
            .join("");
        return reviewTables;
    }
    async _createWalletWarning(username, walletAddress) {
        const { hasToken } = await this._getTokenDisplayForUser(username);
        if (!hasToken) {
            return "";
        }
        if (walletAddress === null) {
            return `<h6>⚠️ Wallet address is not set</h6>`;
        }
        if (walletAddress === undefined) {
            return `<h6>⚠️ Error fetching wallet</h6>`;
        }
        return "";
    }
    _createPermitSaveWarning(result) {
        if (!result.permitSaveErrors?.length) {
            return "";
        }
        const linkUrl = result.permitUrl || result.explorerUrl;
        const linkLabel = result.permitUrl ? "Claim" : "View";
        const safeLink = linkUrl ? this._encodeHTML(linkUrl) : "";
        const rows = result.permitSaveErrors
            .map((error) => {
            const amount = error.amount ? this._encodeHTML(error.amount) : "-";
            const nonce = error.nonce ? this._encodeHTML(error.nonce) : "-";
            const message = error.message ? this._encodeHTML(error.message) : "Unknown error";
            const linkCell = safeLink ? `<a href="${safeLink}" target="_blank" rel="noopener">${linkLabel}</a>` : "-";
            return `<tr><td>${amount}</td><td>${nonce}</td><td>${message}</td><td>${linkCell}</td></tr>`;
        })
            .join("");
        return `<table><thead><tr><th>Amount</th><th>Nonce</th><th>Reason</th><th>Claim</th></tr></thead><tbody>${rows}</tbody></table>`;
    }
    async _createRewardLink(result, tokenSymbol) {
        if (result.permitUrl || result.explorerUrl) {
            return `<a href="${result.permitUrl || result.explorerUrl}" target="_blank" rel="noopener">[ ${result.total} ${tokenSymbol} ]</a>`;
        }
        const isRewardClaimed = await this.isRewardClaimed(result);
        return `[ ${result.total} ${tokenSymbol} ]${isRewardClaimed ? " ☑️" : ""}`;
    }
    _createPermitSaveWarningLabel(result) {
        if (!result.permitSaveErrors?.length) {
            return "";
        }
        return "&nbsp;⚠️ Error saving permit to database";
    }
    async _generateHtml(username, result, taskReward, stripComments = false) {
        const sortedTasks = result.comments?.reduce((acc, curr) => {
            if (curr.commentType & CommentKind.ISSUE) {
                if (curr.commentType & CommentAssociation.SPECIFICATION) {
                    acc.issues.specification = curr;
                }
                else {
                    acc.issues.comments.push(curr);
                }
            }
            else if (curr.commentType & CommentKind.PULL) {
                if (curr.commentType & CommentAssociation.SPECIFICATION) {
                    acc.reviews.specification = curr;
                }
                else {
                    acc.reviews.comments.push(curr);
                }
            }
            return acc;
        }, { issues: { specification: null, comments: [] }, reviews: { specification: null, comments: [] } });
        const { symbol: tokenSymbol } = await this._getTokenDisplayForUser(username);
        const rewardsSum = result.comments?.reduce((acc, curr) => acc.add(curr.score?.reward ?? 0), new Decimal(0)) ??
            new Decimal(0);
        const isCapped = taskReward > 0 && rewardsSum.gt(taskReward);
        return `
    <details>
      <summary>
        <b>
          <h3>
            &nbsp;
            ${await this._createRewardLink(result, tokenSymbol)}
            &nbsp;
          </h3>
          <h6>
            @${username}${this._createPermitSaveWarningLabel(result)}
          </h6>
        </b>
      </summary>
      ${await this._createWalletWarning(username, result.walletAddress)}
      ${this._createPermitSaveWarning(result)}
      ${result.feeRate !== undefined ? `<h6>⚠️ ${new Decimal(result.feeRate).mul(100)}% fee rate has been applied. Consider using the&nbsp;<a href="https://dao.ubq.fi/dollar" target="_blank" rel="noopener">Ubiquity Dollar</a>&nbsp;for no fees.</h6>` : ""}
      ${isCapped ? `<h6>⚠️ Your rewards have been limited to the task price of ${taskReward} ${tokenSymbol}.</h6>` : ""}
      <h6>Contributions Overview</h6>
      <table>
        <thead>
          <tr>
            <th>View</th>
            <th>Contribution</th>
            <th>Count</th>
            <th>Reward</th>
          </tr>
        </thead>
        <tbody>
          ${this._createContributionRows(result, sortedTasks)}
        </tbody>
      </table>
      ${!stripComments ? this._createSimplificationRows(result) : ""}
      ${!stripComments && this.isPullRequest() ? this._createReviewRows(result) : ""}
      ${!stripComments &&
            sortedTasks &&
            (sortedTasks.issues.comments.length ||
                sortedTasks.reviews.comments.length ||
                sortedTasks.issues.specification ||
                sortedTasks.reviews.specification)
            ? `<h6>Conversation Incentives</h6>
      <table>
        <thead>
          <tr>
            <th>Comment</th>
            <th>Formatting</th>
            <th>Relevance</th>
            <th>Priority</th>
            <th>Reward</th>
          </tr>
        </thead>
        <tbody>
          ${this._createIncentiveRows(sortedTasks)}
        </tbody>
      </table>`
            : ""}
    </details>
    `
            .replace(/(\r?\n|\r)\s*/g, "") // Remove newlines and leading spaces/tabs after them
            .replace(/\s*(<\/?[^>]+>)\s*/g, "$1") // Trim spaces around HTML tags
            .trim();
    }
}
