// src/utils/keys.ts
import sodium from "libsodium-wrappers";
async function decrypt(encryptedText, x25519PrivateKey) {
  await sodium.ready;
  const publicKey = await getPublicKey(x25519PrivateKey);
  const binaryPublic = sodium.from_base64(publicKey, sodium.base64_variants.URLSAFE_NO_PADDING);
  const binaryPrivate = sodium.from_base64(x25519PrivateKey, sodium.base64_variants.URLSAFE_NO_PADDING);
  const binaryEncryptedText = sodium.from_base64(encryptedText, sodium.base64_variants.URLSAFE_NO_PADDING);
  return sodium.crypto_box_seal_open(binaryEncryptedText, binaryPublic, binaryPrivate, "text");
}
async function getPublicKey(x25519PrivateKey) {
  await sodium.ready;
  const binaryPrivate = sodium.from_base64(x25519PrivateKey, sodium.base64_variants.URLSAFE_NO_PADDING);
  return sodium.crypto_scalarmult_base(binaryPrivate, "base64");
}
function parseDecryptedPrivateKey(decryptedPrivateKey) {
  const result = {
    privateKey: null,
    allowedOrganizationId: null,
    allowedRepositoryId: null
  };
  const privateKeyParts = decryptedPrivateKey.split(":");
  if (privateKeyParts.length === 1) {
    result.privateKey = privateKeyParts[0];
  }
  if (privateKeyParts.length === 2) {
    result.privateKey = privateKeyParts[0];
    result.allowedOrganizationId = Number(privateKeyParts[1]);
  }
  if (privateKeyParts.length === 3) {
    result.privateKey = privateKeyParts[0];
    result.allowedOrganizationId = Number(privateKeyParts[1]);
    result.allowedRepositoryId = Number(privateKeyParts[2]);
  }
  return result;
}

// src/utils/get-fastest-provider.ts
import { ethers } from "ethers";
async function getRpcProvider(networkId) {
  try {
    const provider = new ethers.providers.JsonRpcProvider(`https://permit2-rpc-proxy.deno.dev/${networkId}`);
    await provider.getBlockNumber();
    return provider;
  } catch (e) {
    throw new Error(`Failed to get provider for networkId: ${networkId}`);
  }
}

// src/handlers/generate-erc20-permit.ts
async function generateErc20PermitSignature(contextOrPayload, username, amount, tokenAddress) {
  let logger;
  const _username = username;
  let walletAddress;
  let issueNodeId;
  let evmNetworkId;
  let evmPrivateEncrypted;
  let userId;
  if ("issueNodeId" in contextOrPayload) {
    logger = contextOrPayload.logger;
    walletAddress = contextOrPayload.walletAddress;
    evmNetworkId = contextOrPayload.evmNetworkId;
    evmPrivateEncrypted = contextOrPayload.evmPrivateEncrypted;
    issueNodeId = contextOrPayload.issueNodeId;
    userId = contextOrPayload.userId;
  } else {
    const config = contextOrPayload.config;
    logger = contextOrPayload.logger;
    const { evmNetworkId: configEvmNetworkId, evmPrivateEncrypted: configEvmPrivateEncrypted } = config;
    const { data: userData } = await contextOrPayload.octokit.rest.users.getByUsername({ username: _username });
    if (!userData) {
      throw new Error(`GitHub user was not found for id ${_username}`);
    }
    userId = userData.id;
    const { wallet } = contextOrPayload.adapters.supabase;
    walletAddress = await wallet.getWalletByUserId(userId);
    evmNetworkId = configEvmNetworkId;
    evmPrivateEncrypted = configEvmPrivateEncrypted;
    if ("issue" in contextOrPayload.payload) {
      issueNodeId = contextOrPayload.payload.issue.node_id;
    } else if ("pull_request" in contextOrPayload.payload) {
      issueNodeId = contextOrPayload.payload.pull_request.node_id;
    } else {
      throw new Error("Issue Id is missing");
    }
  }
  if (!_username) {
    throw new Error("User was not found");
  }
  if (!walletAddress) {
    const errorMessage = "ERC20 Permit generation error: Wallet not found";
    logger.error(errorMessage);
    throw new Error(errorMessage);
  }
  const provider = await getRpcProvider(evmNetworkId);
  if (!provider) {
    logger.error("Provider is not defined");
    throw new Error("Provider is not defined");
  }
  const privateKey = await getPrivateKey(evmPrivateEncrypted, logger);
  const adminWallet = await getAdminWallet(privateKey, provider, logger);
  const tokenDecimals = await getTokenDecimals(tokenAddress, provider, logger);
  const permitTransferFromData = {
    permitted: {
      token: tokenAddress,
      amount: utils.parseUnits(amount.toString(), tokenDecimals)
    },
    spender: walletAddress,
    nonce: BigInt(utils.keccak256(utils.toUtf8Bytes(`${userId}-${issueNodeId}`))),
    deadline: MaxUint256
  };
  const { domain, types: types2, values } = SignatureTransfer.getPermitData(permitTransferFromData, PERMIT2_ADDRESS, evmNetworkId);
  try {
    const signature = await adminWallet._signTypedData(domain, types2, values);
    const erc20Permit = {
      tokenType: "ERC20" /* ERC20 */,
      tokenAddress: permitTransferFromData.permitted.token,
      beneficiary: permitTransferFromData.spender,
      nonce: permitTransferFromData.nonce.toString(),
      deadline: permitTransferFromData.deadline.toString(),
      amount: permitTransferFromData.permitted.amount.toString(),
      owner: adminWallet.address,
      signature,
      networkId: evmNetworkId
    };
    logger.info("Generated ERC20 permit2 signature", erc20Permit);
    return erc20Permit;
  } catch (error) {
    logger.error(`Failed to sign typed data: ${error}`);
    throw error;
  }
}
async function getPrivateKey(evmPrivateEncrypted, logger) {
  try {
    const privateKeyDecrypted = await decrypt(evmPrivateEncrypted, String(process.env.X25519_PRIVATE_KEY));
    const privateKeyParsed = parseDecryptedPrivateKey(privateKeyDecrypted);
    const privateKey = privateKeyParsed.privateKey;
    if (!privateKey) throw new Error("Private key is not defined");
    return privateKey;
  } catch (error) {
    const errorMessage = `Failed to decrypt a private key: ${error}`;
    logger.error(errorMessage);
    throw new Error(errorMessage);
  }
}
async function getAdminWallet(privateKey, provider, logger) {
  try {
    return new ethers2.Wallet(privateKey, provider);
  } catch (error) {
    const errorMessage = `Failed to instantiate wallet: ${error}`;
    logger.debug(errorMessage);
    throw new Error(errorMessage);
  }
}
async function getTokenDecimals(tokenAddress, provider, logger) {
  try {
    const erc20Abi = ["function decimals() public view returns (uint8)"];
    const tokenContract = new ethers2.Contract(tokenAddress, erc20Abi, provider);
    return await tokenContract.decimals();
  } catch (error) {
    const errorMessage = `Failed to get token decimals for token: ${tokenAddress}, ${error}`;
    logger.debug(errorMessage, { error });
    throw new Error(errorMessage);
  }
}

// src/handlers/generate-erc721-permit.ts
import { MaxUint256 as MaxUint2562 } from "@uniswap/permit2-sdk";
import { Wallet, utils as utils2 } from "ethers";

// src/types/typeguards.ts
function isIssueEvent(context2) {
  return context2.eventName.startsWith("issues.");
}

// src/handlers/generate-erc721-permit.ts
var SIGNING_DOMAIN_NAME = "NftReward-Domain";
var SIGNING_DOMAIN_VERSION = "1";
var types = {
  MintRequest: [
    { name: "beneficiary", type: "address" },
    { name: "deadline", type: "uint256" },
    { name: "keys", type: "bytes32[]" },
    { name: "nonce", type: "uint256" },
    { name: "values", type: "string[]" }
  ]
};
async function generateErc721PermitSignature(contextOrPermitPayload, username, contributionType) {
  let _logger;
  let _nftContractAddress;
  let _evmNetworkId;
  let _nftMinterPrivateKey;
  let _userId;
  let _walletAddress;
  let _issueNodeId;
  let _organizationName;
  let _repositoryName;
  let _username = username;
  if ("evmNetworkId" in contextOrPermitPayload) {
    _logger = contextOrPermitPayload.logger;
    _nftContractAddress = contextOrPermitPayload.nftContractAddress;
    _nftMinterPrivateKey = contextOrPermitPayload.nftMinterPrivateKey;
    _evmNetworkId = contextOrPermitPayload.evmNetworkId;
    _walletAddress = contextOrPermitPayload.walletAddress;
    _issueNodeId = contextOrPermitPayload.issueNodeId;
    _organizationName = contextOrPermitPayload.organizationName;
    _repositoryName = contextOrPermitPayload.repositoryName;
    _userId = contextOrPermitPayload.userId;
  } else {
    const { NFT_MINTER_PRIVATE_KEY, NFT_CONTRACT_ADDRESS } = contextOrPermitPayload.env;
    _logger = contextOrPermitPayload.logger;
    if (!NFT_MINTER_PRIVATE_KEY) {
      const errorMessage = "NFT minter private key is not defined";
      _logger.error(errorMessage);
      throw new Error(errorMessage);
    }
    if (!NFT_CONTRACT_ADDRESS) {
      const errorMessage = "NFT contract address is not defined";
      _logger.error(errorMessage);
      throw new Error(errorMessage);
    }
    const { evmNetworkId } = contextOrPermitPayload.config;
    const adapters = contextOrPermitPayload.adapters;
    _nftContractAddress = NFT_CONTRACT_ADDRESS;
    _evmNetworkId = evmNetworkId;
    _nftMinterPrivateKey = NFT_MINTER_PRIVATE_KEY;
    _username = username;
    if (isIssueEvent(contextOrPermitPayload)) {
      _issueNodeId = contextOrPermitPayload.payload.issue.node_id;
    } else {
      throw new Error("Issue Id is missing.");
    }
    _organizationName = contextOrPermitPayload.payload.repository.owner.login;
    _repositoryName = contextOrPermitPayload.payload.repository.name;
    const { data: userData } = await contextOrPermitPayload.octokit.rest.users.getByUsername({ username: _username });
    if (!userData) {
      throw new Error(`GitHub user was not found for id ${_username}`);
    }
    _userId = userData.id;
    const walletAddress = await adapters.supabase.wallet.getWalletByUserId(_userId);
    if (!walletAddress) {
      _logger.error("No wallet found for user");
      throw new Error("No wallet found for user");
    }
    _walletAddress = walletAddress;
  }
  const provider = await getRpcProvider(_evmNetworkId);
  if (!provider) {
    _logger.error("Provider is not defined");
    throw new Error("Provider is not defined");
  }
  let adminWallet;
  try {
    adminWallet = new Wallet(_nftMinterPrivateKey, provider);
  } catch (error) {
    _logger.error("Failed to instantiate wallet", error);
    throw new Error("Failed to instantiate wallet");
  }
  const erc721Metadata = {
    GITHUB_ORGANIZATION_NAME: _organizationName,
    GITHUB_REPOSITORY_NAME: _repositoryName,
    GITHUB_ISSUE_NODE_ID: _issueNodeId,
    GITHUB_USERNAME: _username,
    GITHUB_CONTRIBUTION_TYPE: contributionType
  };
  const metadata = Object.entries(erc721Metadata);
  const erc721SignatureData = {
    beneficiary: _walletAddress,
    deadline: MaxUint2562.toBigInt(),
    keys: metadata.map(([key]) => utils2.keccak256(utils2.toUtf8Bytes(key))),
    nonce: BigInt(utils2.keccak256(utils2.toUtf8Bytes(`${_userId}-${_issueNodeId}`))),
    values: metadata.map(([, value]) => value)
  };
  const domain = {
    name: SIGNING_DOMAIN_NAME,
    version: SIGNING_DOMAIN_VERSION,
    verifyingContract: _nftContractAddress,
    chainId: _evmNetworkId
  };
  const signature = await adminWallet._signTypedData(domain, types, erc721SignatureData).catch((error) => {
    _logger.error("Failed to sign typed data", error);
    throw new Error(`Failed to sign typed data: ${error}`);
  });
  const erc721Permit = {
    tokenType: "ERC721" /* ERC721 */,
    tokenAddress: _nftContractAddress,
    beneficiary: _walletAddress,
    amount: "1",
    nonce: erc721SignatureData.nonce.toString(),
    deadline: erc721SignatureData.deadline.toString(),
    signature,
    owner: adminWallet.address,
    networkId: _evmNetworkId,
    erc721Request: {
      keys: erc721SignatureData.keys.map((key) => key.toString()),
      values: erc721SignatureData.values,
      metadata: erc721Metadata
    }
  };
  console.info("Generated ERC721 permit signature", { erc721Permit });
  return erc721Permit;
}

// src/handlers/generate-payout-permit.ts
async function generatePayoutPermit(context2, permitRequests) {
  const permits = [];
  for (const permitRequest of permitRequests) {
    const { type, amount, username, contributionType, tokenAddress } = permitRequest;
    let permit;
    switch (type) {
      case "ERC20":
        permit = await generateErc20PermitSignature(context2, username, amount, tokenAddress);
        break;
      case "ERC721":
        permit = await generateErc721PermitSignature(context2, username, contributionType);
        break;
      default:
        context2.logger.error(`Invalid permit type: ${type}`);
        continue;
    }
    permits.push(permit);
  }
  return permits;
}

// src/handlers/encode-decode.ts
function encodePermits(permits) {
  const permitsDto = permits.map((permit) => {
    if (permit.tokenType === "ERC20" /* ERC20 */) {
      return {
        type: "erc20-permit",
        permit: {
          permitted: {
            token: permit.tokenAddress,
            amount: permit.amount
          },
          nonce: permit.nonce,
          deadline: permit.deadline
        },
        transferDetails: {
          to: permit.beneficiary,
          requestedAmount: permit.amount
        },
        owner: permit.owner,
        signature: permit.signature,
        networkId: permit.networkId
      };
    } else {
      if (permit.erc721Request) {
        return {
          type: "erc721-permit",
          permit: {
            permitted: {
              token: permit.tokenAddress,
              amount: permit.amount
            },
            nonce: permit.nonce,
            deadline: permit.deadline
          },
          transferDetails: {
            to: permit.beneficiary,
            requestedAmount: permit.amount
          },
          owner: permit.owner,
          signature: permit.signature,
          networkId: permit.networkId,
          nftMetadata: permit.erc721Request.metadata,
          request: {
            beneficiary: permit.beneficiary,
            deadline: permit.deadline,
            keys: permit.erc721Request?.keys,
            nonce: permit.nonce,
            values: permit.erc721Request?.values
          }
        };
      } else {
        return null;
      }
    }
  }).filter((o) => o);
  return Buffer.from(JSON.stringify(permitsDto)).toString("base64");
}
function decodePermits(base64) {
  const decoded = atob(base64);
  const objs = JSON.parse(decoded);
  const result = [];
  for (const obj of objs) {
    const tokenType = obj.type === "erc20-permit" ? "ERC20" /* ERC20 */ : "ERC721" /* ERC721 */;
    if (tokenType === "ERC721" /* ERC721 */) {
      result.push({
        amount: obj.permit.permitted.amount,
        beneficiary: obj.transferDetails.to,
        deadline: obj.permit.deadline,
        networkId: obj.networkId,
        nonce: obj.permit.nonce,
        owner: obj.owner,
        signature: obj.signature,
        tokenAddress: obj.permit.permitted.token,
        tokenType,
        ...obj.type === "erc721-permit" && obj.nftMetadata && {
          erc721Request: {
            metadata: obj.nftMetadata,
            keys: obj.request?.keys ?? [],
            values: obj.request?.values ?? []
          }
        }
      });
    } else {
      result.push({
        amount: obj.permit.permitted.amount,
        beneficiary: obj.transferDetails.to,
        deadline: obj.permit.deadline,
        networkId: obj.networkId,
        nonce: obj.permit.nonce,
        owner: obj.owner,
        signature: obj.signature,
        tokenAddress: obj.permit.permitted.token,
        tokenType
      });
    }
  }
  return result;
}

