// src/generate-permits-from-context.ts
import * as github from "@actions/github";
import { Octokit } from "@octokit/rest";
import { Value } from "@sinclair/typebox/value";
import { createClient } from "@supabase/supabase-js";

// src/handlers/register-wallet.ts
import { ethers as ethers3, constants } from "ethers";
async function registerWallet(context2, address) {
  const payload = context2.payload;
  const logger = context2.logger;
  const sender = payload.sender.login;
  const senderID = payload.sender.id;
  const body = payload.comment.body;
  const adapters = context2.adapters;
  const ensName = extractEnsName(body.replace("/wallet", "").trim());
  if (!address && ensName) {
    logger.info("Trying to resolve address from ENS name", { ensName });
    address = await resolveAddress(ensName);
    if (!address) {
      logger.fatal("Resolving address from ENS name failed", { ensName });
      return false;
    }
    logger.info("Resolved address from ENS name", { ensName, address });
  }
  if (!address) {
    logger.info("Skipping to register a wallet address because both address/ens doesn't exist");
    return false;
  }
  if (address === constants.AddressZero) {
    logger.error("Skipping to register a wallet address because user is trying to set their address to null address");
    return false;
  }
  if (address && senderID) {
    const { wallet, user } = adapters.supabase;
    const userRecord = await user.getUserById(senderID);
    try {
      if (!userRecord) {
        await user.upsertUser(senderID, sender);
        await wallet.upsertWallet(senderID, address);
      } else {
        await wallet.upsertWallet(senderID, address);
      }
      logger.info("Successfully registered wallet address", { sender, address });
      return true;
    } catch (err) {
      logger.error("Error while registering wallet address", { sender, address, err });
    }
  } else {
    logger.error(`No address found in comment: ${body}`);
  }
  return false;
}
async function resolveAddress(ensName) {
  const provider = new ethers3.providers.JsonRpcProvider(`https://eth.llamarpc.com`);
  return await provider.resolveName(ensName).catch((err) => {
    console.trace({ err });
    return null;
  });
}
function extractEnsName(text) {
  const ensRegex = /^(?=.{3,40}$)([a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}$/gm;
  const match = text.match(ensRegex);
  if (match) {
    const ensName = match[0];
    return ensName.toLowerCase();
  }
}

// src/types/env.ts
import { Type as T } from "@sinclair/typebox";
import "dotenv/config";
var envSchema = T.Object({
  GITHUB_TOKEN: T.String(),
  SUPABASE_URL: T.String(),
  SUPABASE_KEY: T.String(),
  NFT_MINTER_PRIVATE_KEY: T.Optional(T.String()),
  NFT_CONTRACT_ADDRESS: T.Optional(T.String())
});

// src/types/plugin-input.ts
import { Type as T2 } from "@sinclair/typebox";
var permitRequestSchema = T2.Object({
  type: T2.Union([T2.Literal("ERC20"), T2.Literal("ERC721")]),
  username: T2.String(),
  amount: T2.Number(),
  contributionType: T2.String(),
  tokenAddress: T2.String()
});
var permitGenerationSettingsSchema = T2.Object({
  evmNetworkId: T2.Number(),
  evmPrivateEncrypted: T2.String(),
  permitRequests: T2.Array(permitRequestSchema)
});

// src/generate-permits-from-context.ts
async function generatePermitsFromContext() {
  const webhookPayload = github.context.payload.inputs;
  const env = Value.Decode(envSchema, process.env);
  const settings = Value.Decode(permitGenerationSettingsSchema, JSON.parse(webhookPayload.settings));
  const inputs = {
    stateId: webhookPayload.stateId,
    eventName: webhookPayload.eventName,
    eventPayload: JSON.parse(webhookPayload.eventPayload),
    settings,
    authToken: webhookPayload.authToken,
    ref: webhookPayload.ref
  };
  const octokit = new Octokit({ auth: inputs.authToken });
  const supabaseClient = createClient(env.SUPABASE_URL, env.SUPABASE_KEY);
  const context2 = {
    eventName: inputs.eventName,
    payload: inputs.eventPayload,
    config: inputs.settings,
    octokit,
    env,
    logger: {
      debug(message, ...optionalParams) {
        console.debug(message, ...optionalParams);
      },
      info(message, ...optionalParams) {
        console.log(message, ...optionalParams);
      },
      warn(message, ...optionalParams) {
        console.warn(message, ...optionalParams);
      },
      error(message, ...optionalParams) {
        console.error(message, ...optionalParams);
      },
      fatal(message, ...optionalParams) {
        console.error(message, ...optionalParams);
      }
    },
    adapters: {}
  };
  context2.adapters = createAdapters(supabaseClient, context2);
  if (context2.eventName === "issue_comment.created") {
    await handleSlashCommands(context2, octokit);
  } else {
    const permits = await generatePayoutPermit(context2, settings.permitRequests);
    await returnDataToKernel(env.GITHUB_TOKEN, inputs.stateId, permits);
    return JSON.stringify(permits);
  }
  return null;
}
