import { SupabaseClient } from "@supabase/supabase-js";
import { createActionsPlugin } from "@ubiquity-os/plugin-sdk";
import { createAdapters } from "./adapters";
import { run } from "./run";
import envConfigSchema from "./types/env-type";
import { pluginSettingsSchema } from "./types/plugin-input";
export default createActionsPlugin((context) => {
    const supabaseClient = new SupabaseClient(context.env.SUPABASE_URL, context.env.SUPABASE_KEY);
    const adapters = createAdapters(supabaseClient, context);
    return run({ ...context, adapters });
}, {
    logLevel: process.env.LOG_LEVEL ?? "info",
    settingsSchema: pluginSettingsSchema,
    envSchema: envConfigSchema,
    ...(process.env.KERNEL_PUBLIC_KEY && { kernelPublicKey: process.env.KERNEL_PUBLIC_KEY }),
    postCommentOnError: true,
    bypassSignatureVerification: process.env.NODE_ENV === "local",
});
